-- creature_classlevelstats: repair levels 84-255.
--
-- A. damage_base/damage_exp1/damage_exp2 lost their decimal separator from
--    level 86 up (`51,2373` stored as `512373`), so any creature above 85
--    rolled six-figure base melee damage.
-- B. levels 84-85 carried stock AzerothCore's `1` placeholders for
--    basehp0/basehp1/basehp2/basearmor and `0` for rangedattackpower, which
--    left level-85 exp=2 creatures (961 live spawns on maps 750/861) at 1 HP.
--
-- Generated by Custom/Documentation/scripts/fix_creature_classlevelstats.py
-- Source of truth: Custom/Levelstats 255/255_creature_classlevelstats.csv

DELETE FROM `creature_classlevelstats` WHERE `level` >= 84 AND `class` IN (1,2,4,8);
